// AI: below section was generated by an AI
//
// Writes flash.json for a signed release folder: the four parts a blank board needs, with the
// offset, size and SHA-256 of each, for the browser flasher (lumen-shared contracts/firmware.md,
// "Serial provisioning" > "Release parts"). Run it after tools/sign-release.mjs:
//
//   node tools/flash-manifest.mjs --dir dist/esp32s3_lumen_<env>-<version>
//
// It reads no key and signs nothing. Only firmware.bin is signed (manifest.json); this script
// refuses a folder whose firmware.bin isn't the signed one, a bench folder, a folder whose image
// points at the other env's host, and a partition table that isn't the Lumen layout. Upload
// flash.json and the three extra parts with firmware.bin and manifest.json in /admin/firmware.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { basename, join, resolve } from 'node:path';

const USAGE = 'Usage: node tools/flash-manifest.mjs --dir dist/esp32s3_lumen_<env>-<version>';

function fail(msg) {
  console.error(`flash-manifest: ${msg}`);
  process.exit(1);
}

const args = process.argv.slice(2);
if (args.length !== 2 || args[0] !== '--dir') fail(USAGE);
const dir = resolve(args[1]);

// Same rules as the station's check_release(): bench images never go on a board that ships, and
// the folder name says which env and version it holds.
const name = basename(dir);
if (/BENCH|DO_NOT_SHIP/.test(name)) fail(`${name} is a bench test image; those are never flashed onto a board that ships`);
const m = /^esp32s3_lumen_(prod|dev)-([\x21-\x7e]+)$/.exec(name);
if (!m) fail(`${name} is not an esp32s3_lumen_<prod|dev>-<version> release folder`);
const [, env, folderVersion] = m;

// Build-default backend host compiled into each env (platformio_override.ini, LUMEN_DEVICE_HOST).
const ENV_HOSTS = {
  prod: 'devices.buylumen.com',
  dev: 'glowline-app-dev.cedericfrank.workers.dev',
};

// Where each part goes. The bootloader and partition table offsets are fixed by the ESP32-S3 ROM
// and ESP-IDF; the rest come from tools/WLED_ESP32_16MB_9MB_FS.csv. maxSize = room before the next
// region, so an oversized part can't overwrite its neighbour.
const PARTS = [
  { file: 'bootloader.bin', offset: 0x0, maxSize: 0x8000 },
  { file: 'partitions.bin', offset: 0x8000, maxSize: 0x1000 },
  { file: 'boot_app0.bin', offset: 0xe000, maxSize: 0x2000 },
  { file: 'firmware.bin', offset: 0x10000, maxSize: 0x300000 },
];

// The Lumen partition table (tools/WLED_ESP32_16MB_9MB_FS.csv), frozen: NVS, the OTA slots and the
// file system must sit where the station, the usermod and OTA expect them.
const TABLE = [
  { label: 'nvs', type: 1, subtype: 2, offset: 0x9000, size: 0x5000 },
  { label: 'otadata', type: 1, subtype: 0, offset: 0xe000, size: 0x2000 },
  { label: 'app0', type: 0, subtype: 0x10, offset: 0x10000, size: 0x300000 },
  { label: 'app1', type: 0, subtype: 0x11, offset: 0x310000, size: 0x300000 },
  { label: 'spiffs', type: 1, subtype: 0x82, offset: 0x610000, size: 0x9e0000 },
  { label: 'coredump', type: 1, subtype: 3, offset: 0xff0000, size: 0x10000 },
];

function read(file) {
  const path = join(dir, file);
  if (!existsSync(path)) fail(`${path} is missing (copy it at release time, see usermods/glowline/readme.md "Signing a release")`);
  return readFileSync(path);
}

const sha256 = (buf) => createHash('sha256').update(buf).digest('hex');

// 1. firmware.bin must be the image manifest.json signed.
let manifest;
try {
  manifest = JSON.parse(read('manifest.json').toString('utf8'));
} catch (e) {
  fail(`manifest.json is not valid JSON (${e.message})`);
}
if (manifest.version !== folderVersion) fail(`manifest.json is for version "${manifest.version}", the folder is ${folderVersion}`);
if (typeof manifest.signature !== 'string' || !manifest.signature) fail('manifest.json has no signature: sign the image first (tools/sign-release.mjs)');
const app = read('firmware.bin');
if (app.length !== manifest.size) fail(`firmware.bin is ${app.length} bytes, manifest.json says ${manifest.size}`);
if (sha256(app) !== String(manifest.sha256).toLowerCase()) fail('firmware.bin does not match the SHA-256 in manifest.json: not the signed image');

// 2. The image dials its own env's host and not the other one's.
for (const [other, host] of Object.entries(ENV_HOSTS)) {
  const has = app.includes(Buffer.from(host, 'latin1'));
  if (other === env && !has) fail(`firmware.bin does not contain the ${env} host ${host}: wrong env`);
  if (other !== env && has) fail(`firmware.bin contains the ${other} host ${host}, but the folder is ${env}`);
}

// 3. The other parts look like what they claim to be.
const bootloader = read('bootloader.bin');
if (bootloader[0] !== 0xe9) fail('bootloader.bin does not start with the ESP image magic byte 0xE9');
const table = read('partitions.bin');
for (let i = 0; i < TABLE.length; i++) {
  const e = table.subarray(i * 32, i * 32 + 32);
  const want = TABLE[i];
  const got = e.length === 32 && e[0] === 0xaa && e[1] === 0x50 && {
    type: e[2], subtype: e[3], offset: e.readUInt32LE(4), size: e.readUInt32LE(8),
    label: e.subarray(12, 28).toString('latin1').replace(/\0.*$/s, ''),
  };
  if (!got || got.label !== want.label || got.type !== want.type || got.subtype !== want.subtype
      || got.offset !== want.offset || got.size !== want.size) {
    fail(`partitions.bin entry ${i + 1} is not ${want.label} at 0x${want.offset.toString(16)} (0x${want.size.toString(16)} bytes): not the Lumen partition table`);
  }
}
read('boot_app0.bin');

// 4. Write flash.json.
const parts = PARTS.map(({ file, offset, maxSize }) => {
  const buf = file === 'firmware.bin' ? app : read(file);
  if (buf.length > maxSize) fail(`${file} is ${buf.length} bytes, more than the 0x${maxSize.toString(16)} bytes at 0x${offset.toString(16)}`);
  return { file, offset, size: buf.length, sha256: sha256(buf) };
});
const out = {
  format: 1,
  version: folderVersion,
  env,
  chip: 'ESP32-S3',
  flashSize: '16MB',
  psramMB: 8,
  parts,
};
writeFileSync(join(dir, 'flash.json'), JSON.stringify(out, null, 2) + '\n');
console.log(`flash-manifest: wrote ${join(args[1], 'flash.json')} (${env} ${folderVersion}, ${parts.length} parts, firmware.bin matches manifest.json)`);
// AI: end
